sp_widget.client_script:
api.controller=function( $rootScope, $scope ) {
  /* widget controller */
  var c = this;
	var g_form = $scope.page.g_form;
	console.log( ">>>> START" );
	console.log( "$scope" );
	console.log( $scope );
	console.log( "g_form.getValue( business_service ).toString()" );
	console.log( g_form.getValue( "business_service" ).toString() );

	c.fieldTypesToReplace = [ "glide_list" ];
	c.formConfig = {}
	c.formConfig.runningFrom = g_form.getValue( "running_from" );
	c.formConfig.entityState = g_form.getValue( "entity_state" );
	c.formConfig.refreshing = [];


	// Handle toggling a service offering event
	$scope.$on( "offeringToggled", function( events, args ) {
		console.log( ">>>> $scope.$on()" );
		console.log( "events" );
		console.log( events );
		console.log( "args" );
		console.log( args );

		var value = g_form.getValue( "requested_offering" );
		var currentSelection = ( value == "" ? [] : g_form.getValue( "requested_offering" ).split( "," ) );
		if ( args.active  ) {
			if ( currentSelection.indexOf( args.sys_id ) == -1 ) {
				currentSelection.push( args.sys_id );

				if ( !c.data.config.showingEnvironments )
					args.nonProductionRelatedOfferings.forEach( function( nonProdRelated ) {
						currentSelection.push( nonProdRelated );
					} )
			}
		} else {
			if ( currentSelection.indexOf( args.sys_id ) != -1 ) {
				currentSelection.splice( currentSelection.indexOf( args.sys_id ), 1 );

				if ( !c.data.config.showingEnvironments )
					args.nonProductionRelatedOfferings.forEach( function( nonProdRelated ) {
						currentSelection.splice( currentSelection.indexOf( nonProdRelated ), 1 );
					} )
			}
		}

		console.log( "currentSelection" );
		console.log( currentSelection );
		g_form.setValue( "requested_offering", currentSelection.join( "," ) );

		console.log( ">>>> $scope.$on() -- End" );
	} )


	// Handle update of a field event
	$rootScope.$on( "field.change", function( event, parms ) {
		console.log( ">>>> $rootScope.$on()" );
		console.log( "event" );
		console.log( event );
		console.log( "parms" );
		console.log( parms );

		if ( parms.field.name == "business_service" ) {
			console.log( ">>>> Business Service updated" );
			$scope.fetchData( "getBusinessServiceOfferings" );
		}

		if ( parms.field.name == "entity" ) {
			console.log( ">>>> Requested for updated" );
			g_form.clearValue( "identity" );
			c.data.config.showList = false;
			c.data.identityConsumedOfferings = undefined;

			try {
				var sysIdIdentity = g_form.getValue( "entity" ).toString();

				if ( typeof sysIdIdentity !== "undefined" && sysIdIdentity !== "" ) {
						$scope.fetchData( "getEntity" );
						c.data.config.enableFetching = true;
						c.data.config.showList = true;
					}
			} catch( err ) {
				g_form.clearValue( "entity" );
				g_form.clearValue( "identity" );
			}
		}

		if ( parms.field.name == "identity" ) {
			console.log( ">>>> Identity updated" );
			c.data.entity = undefined;
			try {
				var sysIdIdentity = g_form.getValue( "identity" ).toString();

				if ( typeof sysIdIdentity !== "undefined" && sysIdIdentity !== "" ) {
						c.data.config.enableFetching = true;
						c.data.config.showList = true;
						$scope.fetchData( "getIdentityOfferings" );
					}
			} catch( err ) {
				g_form.clearValue( "identity" );
			}
		}

		if ( parms.field.name == "requested_offering" ) {
			$scope.refreshGroupedOfferings( g_form.getValue( "requested_offering" ).toString().split( "," ) );
		}

		console.log( ">>>> $rootScope.$on() -- End" );
	} );							


	// Apply the identity consumed offering so the display reflect the identity current status
	// or the one updated from the back end in the requested_offering field, if somehow done that way
	$scope.refreshGroupedOfferings = function( requestedOfferings ) {
		console.log( ">>>> $scope.refreshGroupedOfferings()" );
		console.log( "requestedOfferings" );
		console.log( requestedOfferings );
		// Mets à jour les switches

		if ( Array.isArray( requestedOfferings ) ) {
			for ( var group in c.data.groupedOfferings ) {
//				console.log( "group" );
//				console.log( group );

				c.data.groupedOfferings[ group ].forEach( function( offering ) {
//					console.log( "offering" );
//					console.log( offering );
					offering.active = requestedOfferings.indexOf( offering.sys_id ) !== -1;
				});
			}
		}
		console.log( ">>>> $scope.refreshGroupedOfferings() -- End" );
	};


	// Fetch the data on the server side
	$scope.fetchData = function( action ) {
		console.log( ">>>> $scope.fetchData()" );
		console.log( "action" );
		console.log( action );

		c.data.config.enableFetching = true;

		var serverParms = {};
		serverParms.action = action;
		try {
			serverParms.business_service = g_form.getValue( "business_service" ).toString();
		} catch( err ) {}
		try {
			serverParms.entity = g_form.getValue( "entity" ).toString();
		} catch( err ) {}
		try {
			serverParms.identity = g_form.getValue( "identity" ).toString();
		} catch( err ) {}
		serverParms.config = c.data.config;

		console.log( "serverParms" );
		console.log( serverParms );

		c.server.get( serverParms ).then( function( response ) {
			console.log( ">>>> $scope.fetchData.server.get.then()" );
			console.log( "response" );
			console.log( response );

			c.data.config.enableMore = response.data.config.enableMore;
			c.data.config.showingMore = response.data.config.showingMore;
			c.data.config.enableEnvironment = response.data.config.enableEnvironment
			c.data.config.showingEnvironments = response.data.config.showingEnvironments;
			c.data.config.showList = response.data.config.showList;

			c.data.config.enableFetching = false;

			if ( typeof response.data.groupedOfferings !== "undefined" ) {
				console.log( ">>>> $scope.fetchData.server.get.then() : getBusinessServiceOfferings" );

				$scope.manageGroupedOfferingsResponse( response.data.groupedOfferings );
			}

			if ( typeof response.data.entity !== "undefined" ) {
				console.log( ">>>> $scope.fetchData.server.get.then() : getEntity" );

				$scope.manageEntityResponse( response.data.entity );
			}			

			if ( typeof response.data.identityConsumedOfferings !== "undefined" ) {
				console.log( ">>>> $scope.fetchData.server.get.then() : getIdentityOfferings" );

				$scope.manageConsumedOfferingResponse( response.data.identityConsumedOfferings );
			}

			c.data.config.enableMore = response.data.config.enableMore;
			c.data.config.enableEnvironment = response.data.config.enableEnvironment

			console.log( ">>>> $scope.fetchData.server.get.then() -- End" );
			console.log( "$scope.data" );
			console.log( $scope.data );
		} )		

		console.log( ">>>> $scope.fetchData() -- End" );
	};


	// Handle the fetch data response for an entity
	$scope.manageEntityResponse = function( entity ) {
		console.log( ">>>> $scope.manageEntityResponse" );
		console.log( "entity" );
		console.log( entity );

		c.data.entity = entity;
		if ( typeof entity.mainIdentity !== "undefined" )
			g_form.setValue( "identity", entity.mainIdentity.toString() );
		else
			if ( typeof entity.allIdentity !== "undfefined" && entity.allIdentity.length > 0 )
				g_form.setValue( "identity", entity.allIdentity[ 0 ].toString() );
			else {
				c.data.config.showList = false;
				c.data.config.enableFetching = false;
			}

		g_form.setVisible( "identity", entity.allIdentity.length > 1 || typeof entity.mainIdentity === "undefined" );
	};


	// Handle the fetch data response for a business service offering
	$scope.manageGroupedOfferingsResponse = function( groupedOfferings ) {
		console.log( ">>>> $scope.manageGroupedOfferingsResponse" );
		console.log( "groupedOfferings" );
		console.log( groupedOfferings );

		var customOrder = [ "Production" ];
		c.data.groupedOfferings = $scope.prepareGroupedOfferings( groupedOfferings, customOrder );
	};


	// Handle the fetch data response for an identity consumed offering
	$scope.manageConsumedOfferingResponse = function( consumedOffering ) {
		console.log( ">>>> $scope.manageGroupedOfferingResponse" );

		c.data.identityConsumedOfferings = consumedOffering;
		$scope.refreshGroupedOfferings( consumedOffering );
		g_form.setValue( "requested_offering", consumedOffering.join( "," ) );
		g_form.setValue( "initial_offering", consumedOffering.join( "," ) );
	};


	// Sort the business service service offering to correspond to what is desired
	$scope.prepareGroupedOfferings = function( groupedOfferings, customOrder ) {
		console.log( ">>>> $scope.prepareGroupedOfferings" );
		var sortedOfferings = {};

		// Iterate over the groups in groupedOfferings
		Object.keys( groupedOfferings )
			.sort( function( a, b ) {
			// Custom order logic
			var indexA = customOrder.indexOf( a );
			var indexB = customOrder.indexOf( b );

			if ( indexA !== -1 && indexB !== -1 ) {
				return indexA - indexB; // Both are in customOrder
			}
			if ( indexA !== -1 ) return -1; // a is in customOrder
			if ( indexB !== -1 ) return 1; // b is in customOrder

			// Alphabetical order for the rest
			return a.localeCompare( b );
		} )
			.forEach( function( key ) {
			sortedOfferings[ key ] = groupedOfferings[ key ];
		} );

		console.log( ">>>> $scope.prepareGroupedOfferings -- End" );
		return sortedOfferings;
	};


	// Handle field substitution field by field
	c.fields = ( function() {
		console.log( ">>>> c.fields" );
		var fields = [];
		var fieldNames = g_form.getFieldNames();
		for ( var f in fieldNames ) {
			var field = g_form.getField( fieldNames[ f ] );
			console.log( "field" );
			console.log( field );
			if ( c.fieldTypesToReplace.indexOf( field.type ) > -1 ) {
				field.__c_data = c.data;
				field.__c_data.funct = console.log;
				fields.push( field );
			}
		}

		return fields;
	} )();



	// Initilaisation
	$scope.fetchData( "getBusinessServiceOfferings" );


};

sp_widget.css:
/* Remove the gray background */
._md {
    background-color: white;
}

/* Conteneur principal de la ligne */
.row {
  display: flex;               /* Utilise flexbox pour aligner les éléments */
  justify-content: space-between; /* Place le libellé à gauche et le switch à droite */
}

/* Conteneur principal de la ligne */
.column {
  display: flex;               /* Utilise flexbox pour aligner les éléments */
  flex-direction: column;
}

/* Forcer la largeur à occuper tout l'espace */
.full-width {
  width: 100%;                 /* Étend la ligne sur toute la largeur disponible */
}

/* Libellé */
.label {
  font-size: 1rem;             /* Taille standard du texte */
  font-weight: normal;         /* Peut être ajusté si nécessaire */
}

/* Description sous la ligne 
.description {
  color: gray;
  margin-left: 20px;
} */

/* Switch */
.switch {
  margin-left: auto;           /* Force le switch à aller à l'extrême droite */
}
/*
.md-subheader .md-subheader-inner {
    display: block;
    padding: 0px;
}
*/
.md-subheader {
    background-color: #f3f3f3; /* Light gray for contrast */
    color: #333; /* Darker text color for readability */
    font-weight: bold; /* Make the text stand out */
    padding: 8px 8px; /* Add some padding for spacing */
    border-radius: 4px; /* Slight rounding for a softer appearance */
    margin-bottom: 4px; /* Space below the subheader */
    border-left: 4px solid #009fdf; /* Add a subtle colored left border */
}


md-checkbox.md-checked .md-icon {
    background-color: #009fdf !important; /* Light blue for checked state */
    border-color: #009fdf !important; /* Border in light blue */
}

/* Custom Switch Styles */
md-switch.md-checked .md-thumb {
    background-color: #009fdf !important; /* Light blue for the thumb */
}

md-switch.md-checked .md-bar {
    background-color: #002855 !important; /* Dark blue for the bar */
}


/* Remove fixed height for md-list-item */
md-list-item {
    min-height: auto !important; /* Allow height to adjust dynamically */
    height: auto !important; /* Ensure no fixed height */
    padding: 8px 16px; /* Add consistent padding */
    display: flex; /* Maintain flex layout for proper alignment */
    align-items: flex-start; /* Align content to the top */
}

/* Ensure the switch stays aligned to the right */
md-list-item .row {
    display: flex; /* Flex layout for row alignment */
    justify-content: space-between; /* Push switch to the right */
    width: 100%; /* Ensure full width for alignment */
}

/* Dynamically adjust column alignment */
md-list-item .column {
    display: flex; /* Flexbox for vertical layout */
    flex-direction: column; /* Stack content vertically */
}

/* Reduce space for items without descriptions */
md-list-item .description {
    margin-top: 4px; /* Add spacing above description */
  	margin-left: 20px;
    color: #666; /* Use a lighter text color */
}

/* Switch alignment tweaks */
md-switch {
    margin: 0; /* Remove unnecessary margins */
    align-self: center; /* Center the switch vertically in its container */
}

sp_widget.link:
function link(scope, element, attrs, controller) {
  for ( var f in scope.c.fields ) {
		angular.element( 'div#' + scope.c.fields[ f ].name ).addClass( 'ng-hide' );
	}
}

sp_widget.script:
( function( param ) {

	data.errors = [];

	data.identityConsumedOfferings = undefined;
	data.groupedOfferings = undefined;
	data.entity = undefined;

	if ( typeof input !== "undefined" && typeof input.action !== "undefined" ) {
		data.config = input.config;

		try {
			var entity = ( typeof input.entity !== "undefined" && input.entity != "" 
											? new x_gamlp_idm_lc.ETN_Class_sys_user( input.entity.toString() ) 
											: undefined );
			var identity = ( typeof input.identity !== "undefined" && input.identity != "" 
											? new x_gamlp_cmdb_user.ETN_Class_x_gamlp_cmdb_user_user_account( input.identity.toString() ) 
											: undefined );
			var businessService = ( typeof input.business_service !== "undefined" && input.business_service != "" 
														 ? new x_gamlp_idm_lc.ETN_Class_cmdb_ci_service( input.business_service.toString() ) 
														 : undefined );

			if ( input.action == "getIdentityOfferings" ) {
				try {
					identity.refreshServiceOfferingConsumed( businessService );
					var identityConsumedOfferings = businessService.offerings().getSetIntersection( identity.consumes() );
					data.identityConsumedOfferings = identityConsumedOfferings.toJSON( [ "sys_id" ] ).map( function( field ) { return field.sys_id.value; } );

				} catch( err ) {
					data.errors.push( { code:10011, message: err } )
				}
			}

			if ( input.action == "getEntity" ) {
				data.entity = {};

				try {
					data.entity.mainIdentity = entity.mainIdentity().SysId.toString();
				} catch( err ) {
					data.errors.push( { code:10021, message: err } )
				}

				try {
					data.entity.allIdentity = entity.identities().toJSON( [ "sys_id" ] ).map( function( field ) { return field.sys_id.value.toString(); } );
				} catch( err ) {
					data.errors.push( { code:10022, message: err } )
				}
			}

			if ( input.action == "getBusinessServiceOfferings" ) {
				try {
					var groupedOfferings = {};
					var filter = x_gamlp_idm_lc.ETN_Class_service_offering.FILTER_IS_OPERATIONAL
					var order = x_gamlp_idm_lc.ETN_Class_service_offering.SORT_ON_NAME_ASC();

					businessService.offerings( filter, order ).forEach( function( offering ) {
						if ( typeof groupedOfferings[ offering.UsedFor.toString() ] === "undefined" )
							groupedOfferings[ offering.UsedFor.toString() ] = [];

						var jsonOffering = {};
						jsonOffering.name = offering.Name.toString()
						jsonOffering.sys_id = offering.SysId.toString();
						jsonOffering.short_description = offering.ShortDescription.toString();
						jsonOffering.listed_on_more = offering.XGamlpIdmLcListedOnMore == true;
						jsonOffering.nonProductionRelatedOfferings = offering.nonProductionRelatedOfferings().toJSON( [ "sys_id" ] ).map( function( field ) { return field.sys_id.value; } );

						jsonOffering.active = "false";

						if ( jsonOffering.listed_on_more )
							data.config.enableMore = true;

						if ( offering.UsedFor.toString() != "Production" )
							data.config.enableEnvironment = true;

						groupedOfferings[ offering.UsedFor.toString() ].push( jsonOffering );
//						data.config.showList = true;
					} )

					data.groupedOfferings = groupedOfferings;

				} catch( err ) {
					data.errors.push( { code:10031, message: err } )
				}
			}
		} catch( err ) {
			data.errors.push( { code:10000, message: err } )
		}

	} else {
		data.config = {};
		data.config.enableMore = false
		data.config.showingMore = false;
		data.config.enableEnvironment = false
		data.config.showingEnvironments = false;
		data.config.enableFetching = true;
		data.config.showList = false;
	}

} )();
